def _entries_for_this_bus_and_interface_idx_exist(self, bus_idx, iface_idx):
    """Returns true if there are object entries for the corresponding bus index
    and interface index"""

ref_postcond:
@icontract.snapshot(lambda self: tuple(self.list), name='lst_snapshot')
@icontract.snapshot(lambda self: (self.list[0] if self.list else None), name='first_item')
@icontract.ensure(lambda result, OLD, bus_idx, iface_idx: result == any(
    ('_state' in item[tuple(item.keys())[0]] and
     item[tuple(item.keys())[0]]['_state']['bus_idx'] == bus_idx and
     item[tuple(item.keys())[0]]['_state']['interface_descriptor_idx'] == iface_idx)
    for item in OLD.lst_snapshot
))
@icontract.ensure(lambda result, OLD, self: tuple(self.list) == OLD.lst_snapshot)
@icontract.ensure(lambda result, OLD, bus_idx, iface_idx: (OLD.first_item is None)
                  or (not ('_state' in OLD.first_item[tuple(OLD.first_item.keys())[0]]))
                  or (OLD.first_item[tuple(OLD.first_item.keys())[0]]['_state']['bus_idx'] != bus_idx)
                  or (OLD.first_item[tuple(OLD.first_item.keys())[0]]['_state']['interface_descriptor_idx'] != iface_idx)
                  or result)
@icontract.ensure(lambda result: isinstance(result, bool))
